"use client";

import { motion } from "framer-motion";
import { ArrowLeft, Briefcase, Zap } from "lucide-react";
import Link from "next/link";

export default function CareersPage() {
  return (
    <main className="min-h-screen pt-32 pb-20 px-8 md:px-16 bg-background relative overflow-hidden">
      <div className="max-w-7xl mx-auto space-y-12">
        <Link href="/" className="inline-flex items-center gap-2 text-[10px] font-black uppercase text-primary hover:gap-3 transition-all">
          <ArrowLeft className="w-3 h-3" /> Back Home
        </Link>
        <h1 className="text-7xl font-black text-white tracking-tighter font-outfit">Join the <span className="text-primary italic">Force.</span></h1>
        <p className="text-xl text-white/40 font-bold max-w-2xl leading-relaxed">
          We're looking for world-class senior engineers and designers to join our remote-first collective.
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           {[
             { name: "Senior Frontend", desc: "Next.js & React Expert", icon: Briefcase },
             { name: "Data Architect", desc: "Distributed Systems Specialist", icon: Zap },
             { name: "UX Lead", desc: "Human-centric design lead", icon: Briefcase },
           ].map((p, i) => (
             <div key={i} className="p-10 bg-white/5 border border-white/10 rounded-[2.5rem] hover:bg-white/[0.07] transition-all group">
                <p className="text-sm font-black text-primary uppercase mb-4 tracking-widest">{p.name}</p>
                <p className="text-white/30 text-[11px] font-bold leading-relaxed mb-8">{p.desc}</p>
                <Link href={`/careers/${p.name.toLowerCase().replace(/ /g, "-")}`} className="text-[10px] font-black uppercase text-white group-hover:text-primary transition-colors flex items-center gap-2">Apply Now <ArrowLeft className="w-3 h-3 rotate-180" /></Link>
             </div>
           ))}
        </div>
      </div>
    </main>
  );
}
